M=[dict(id='m1',kc=a,statement='Diffraction is reflection or refraction.',refutation='Diffraction is spreading at a gap or edge; neither a change of medium nor bouncing back is required.',contrast='A wave spreads into the geometrical shadow beyond an aperture or edge.',source='ER 9702 w23 P22 Q5'),dict(id='m2',kc=b,statement='A wider gap gives more spreading.',refutation='For fixed wavelength, a wider gap gives less diffraction.',contrast='Spreading is most marked when gap width is comparable to wavelength.',source='ER 9702 s22 P11 Q28'),dict(id='m3',kc=b,statement='Passing through a gap changes wavelength.',refutation='The medium and frequency remain the same, so wave speed and wavelength remain the same.',contrast='Gap width changes the spread, not wavefront spacing.',source='ER 9702 s22 P11 Q28'),dict(id='m4',kc=b,statement='Increasing amplitude increases the diffraction angle.',refutation='Diffraction depends on wavelength relative to gap width, not amplitude.',contrast='Greater amplitude makes waves larger, not more spread out.',source='ER 9702 w22 P13 Q27')]
items=[]
def add(k,kind,stem,answer,explanation,difficulty=2,rubric=None,options=None,mis=None):
 i=len([x for x in items if x['id'].startswith(sub+'-i')])+1
 x=dict(id=f'{sub}-i{i:02}',kcs=[k],kind=kind,difficulty=difficulty,command_word=stem.split()[0],source={'type':'generated'},stem=stem,marks=1,explanation=explanation,hints=['Think about what happens to the wavefronts.','Compare the gap with the wavelength.','Look at the wavefronts immediately beyond the barrier.'])
 if kind=='short':x['rubric']=rubric
 if kind=='mcq':x.update(options=options,answer=answer,distractors=mis or {},shuffle=True)
 items.append(x)
def short(k,stem,point,groups,explain,d=2):add(k,'short',stem,None,explain,d,[{'point':point,'keywords':groups}])
short(a,'Define diffraction.','Spreading of waves as they pass through a gap or around an edge.',[['spread','spreading'],['gap','edge','aperture']], 'A gap or edge causes wavefronts to spread into the region beyond it.',1)
short(a,'Describe what happens to plane water-wave wavefronts after they pass through a narrow gap.','They spread out as curved wavefronts.',[['spread','curve','circular']], 'The gap acts as a source of curved wavefronts.',2)
short(a,'Explain how waves can reach the region behind an obstacle edge.','They diffract, spreading around the edge into the shadow region.',[['diffract','spreading','spread'],['edge']], 'Diffraction carries wave energy beyond the straight-line shadow.',3)
short(a,'State one situation in which diffraction occurs.','A wave passes through an aperture or around an edge.',[['gap','aperture','edge']], 'Both an aperture and an obstacle edge can cause diffraction.',1)
add(a,'mcq','Identify the wave behaviour when waves spread around the edge of a barrier.','B','Spreading around an edge is diffraction.',2,options={'A':'reflection','B':'diffraction','C':'refraction','D':'polarisation'},mis={'A':'m1','C':'m1'})
short(a,'Explain why a sound can be heard around a corner although the source is hidden.','Sound waves diffract around the edge of the wall. For appreciable spreading, their wavelength is comparable to the opening or edge scale.',[['diffract','spread'],['corner','edge','wall']], 'The sound wave bends into the shadow region by diffraction.',4)
short(b,'Describe a ripple-tank experiment that demonstrates diffraction.','Generate plane waves with a vibrating bar; send them through a gap between barriers; observe curved wavefronts beyond the gap.',[['ripple tank','water'],['gap'],['curved','circular','spread']], 'A vibrating bar and barrier with a gap make the wavefront change visible.',3)
short(b,'State the gap-width condition for pronounced diffraction.','The gap width is of the same order as the wavelength.','same order as wavelength'.split() and [['comparable','same order','similar'],['wavelength']], 'Diffraction is most evident when the aperture is about a wavelength wide.',1)
short(b,'Predict the effect of widening a gap while the incident wavelength stays constant.','The emerging waves spread through a smaller angle.',[['less','smaller','decrease'],['spread','angle','diffraction']], 'Widening the gap makes its width larger relative to the wavelength.',2)
short(b,'Explain why lowering the frequency of water waves at constant depth increases diffraction through a fixed gap.','At constant depth wave speed is approximately constant; $v=f\\lambda$, so lower frequency gives larger wavelength and more spreading.',[['speed','depth'],['wavelength'],['spread','diffraction']], 'Increasing wavelength relative to the gap makes diffraction more pronounced.',4)
short(b,'Compare the wavelength before and after a water wave passes through a gap in the same depth of water.','The wavelength is unchanged. The gap changes the direction of travel but not the medium or frequency.',[['unchanged','same','constant']], 'A barrier does not change wave speed or source frequency.',2)
short(b,'Describe how to change the ripple-tank setup to make diffraction easier to observe when the gap is much wider than the wavelength.','Narrow the gap until its width is comparable to the wavelength, or increase wavelength at fixed gap.',[['narrow','decrease','increase wavelength'],['gap','wavelength']], 'Bring the aperture width and wavelength close together.',4)
