pack=dict(subtopic=sub,spec='9702',version=1,note='Subjects/9702 Physics/08 Superposition/8.2 Diffraction.md',outline='Diffraction is the spreading of waves when they pass through an aperture or around an edge. In a ripple tank, plane water waves reach a barrier with a gap and spread into curved wavefronts beyond it. The amount of spreading depends on the wavelength relative to the gap width: it is pronounced when they are comparable and smaller when the gap is much wider. At unchanged depth, passing through a gap does not change wave speed, frequency or wavelength. Use $v=f\\lambda$ when a frequency change is given.',misconceptions=M,worked=worked,items=items,flashcards=[{'id':'fc1','kc':a,'front':'Define diffraction.','back':'The spreading of waves as they pass through an aperture or around the edge of an obstacle.'}],diagrams=[])
